export function AdjustmentDialog({
  organizationId,
  reconciliationId,
  onClose,
  onSaved,
}: {
  organizationId: string;
  reconciliationId: string;
  onClose: () => void;
  onSaved: () => void;
}) {
  const add = useServerFn(addReconciliationAdjustment);
  const [type, setType] = useState("CREDIT");
  const [amount, setAmount] = useState("");
  const [reason, setReason] = useState("");
  const mutation = useMutation({
    mutationFn: () =>
      add({
        data: {
          organizationId,
          reconciliationId,
          adjustment_type: type as "CREDIT" | "DEBIT",
          amount: Number(amount),
          reason,
        },
      }),
    onSuccess: () => {
      toast.success("Ajuste aplicado");
      onSaved();
    },
    onError: (e: Error) => toast.error(e.message),
  });
  return (
    <Dialog open onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Ajuste comercial</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <p className="text-sm text-muted-foreground">
            Crédito reduz o valor cobrável; débito aumenta. O ajuste não altera a quantidade vendida.
            Motivo é obrigatório.
          </p>
          <div className="grid gap-3 sm:grid-cols-2">
            <label>
              Tipo
              <select className={inputClass} value={type} onChange={(e) => setType(e.target.value)}>
                <option value="CREDIT">Crédito (−) </option>
                <option value="DEBIT">Débito (+)</option>
              </select>
            </label>
            <label>
              Valor (R$)
              <Input
                type="number"
                step="0.01"
                min="0"
